# Diagnostic nonzero Monte Carlo floor; canonical CellChat probabilities remain unchanged.
args<-commandArgs(trailingOnly=TRUE);r<-normalizePath(args[1]);u<-file.path(r,'imaging/I001/CellChat_v2');out<-file.path(r,'audit/first_broad_context_MC_floor_v1');stopifnot(!dir.exists(out));dir.create(out);rows<-list();k<-0
for(d in list.dirs(u,recursive=FALSE)){
 f<-file.path(d,'probability_arrays_PRIVATE.rds');if(!file.exists(f))next
 z<-readRDS(f);b<-100;count<-round(z$pval*b);stopifnot(max(abs(count/b-z$pval))<1e-12);p1<-(count+1)/(b+1);q1<-array(p.adjust(as.vector(p1),'BH'),dim=dim(p1));pp<-sort(as.vector(p1));n<-length(pp);orderp<-order(as.vector(p1));qq<-numeric(n);qq[orderp]<-pmin(1,rev(cummin(rev(pp*n/seq_len(n)))));stopifnot(max(abs(as.vector(q1)-qq))<1e-12)
 k<-k+1;rows[[k]]<-data.frame(interaction_range_um=z$metadata$interaction_range,contact_range_um=z$metadata$contact_range,n_full_typepair_LR_hypotheses=length(z$pval),n_raw_software_nominal_candidates=sum(z$prob>0&z$pval<.05),n_raw_software_BH_candidates=sum(z$prob>0&array(p.adjust(as.vector(z$pval),'BH'),dim=dim(p1))<.05),n_add1_floor_BH_candidates=sum(z$prob>0&q1<.05),n_positive_probability_zero_coded_P=sum(z$prob>0&z$pval==0),MC_floor=1/(b+1),minimum_add1_BH=min(q1[z$prob>0]))
}
t<-do.call(rbind,rows);write.table(t,file.path(out,'all_four_variants_MC_floor_sensitivity.tsv'),sep='\t',quote=FALSE,row.names=FALSE);jsonlite::write_json(list(status='FULL4_VARIANT_NONZERO_MC_FLOOR_SENSITIVITY_REVIEWED_RAW_MODELS_UNCHANGED',UTC=format(Sys.time(),'%Y-%m-%dT%H:%M:%SZ',tz='UTC'),n_variants=nrow(t),nboot=100,scope='(b*p+1)/(b+1) floor diagnostic and whole-model BH; not a new spatial null or full tie-handling calibration; original software p values retained',cell_selection_or_model_rerun=FALSE),file.path(out,'complete.json'),pretty=TRUE,auto_unbox=TRUE)
